class Solution:
    def sameText(self, a: str, b: str) -> bool:
        def screen(keys):
            out = []
            for c in keys:
                if c == "#":
                    if out:
                        out.pop()
                else:
                    out.append(c)
            return out
        return screen(a) == screen(b)

