class Solution {
    public boolean sameText(String a, String b) {
        return screen(a).equals(screen(b));
    }

    private String screen(String keys) {
        StringBuilder out = new StringBuilder();
        for (char c : keys.toCharArray()) {
            if (c == '#') { if (out.length() > 0) out.deleteCharAt(out.length() - 1); }
            else out.append(c);
        }
        return out.toString();
    }
}

