// Rewrites keys into out (as a stack) and returns the text length.
static int screen(const char* keys, char* out) {
    int top = 0;
    for (const char* p = keys; *p; p++) {
        if (*p == '#') { if (top > 0) top--; }
        else out[top++] = *p;
    }
    return top;
}

bool sameText(char* a, char* b) {
    char* x = malloc(strlen(a) + 1);
    char* y = malloc(strlen(b) + 1);
    int nx = screen(a, x), ny = screen(b, y);
    bool same = nx == ny && memcmp(x, y, nx) == 0;
    free(x);
    free(y);
    return same;
}

