class Solution {
    public boolean sameText(String a, String b) {
        int i = a.length() - 1, j = b.length() - 1;
        while (true) {
            i = survivor(a, i);
            j = survivor(b, j);
            if (i < 0 || j < 0) return i < 0 && j < 0;
            if (a.charAt(i) != b.charAt(j)) return false;
            i--;
            j--;
        }
    }

    private int survivor(String s, int i) {
        int skip = 0;
        for (; i >= 0; i--) {
            if (s.charAt(i) == '#') skip++;
            else if (skip > 0) skip--;
            else return i;
        }
        return -1;
    }
}

